INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beendet break nur die aktuelle Iteration?', 2, '[{"text": "Nein", "correct": true, "because": "Beendet gesamte Schleife"}, {"text": "Ja", "correct": false, "because": "Continue überspringt nur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit continue?', 3, '[{"text": "Iteration überspringen", "correct": true, "because": "Springt zur nächsten"}, {"text": "Schleife beenden", "correct": false, "because": "Break tut das"}, {"text": "Code optimieren", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle steuern Schleifen?', 5, '[{"text": "Break", "correct": true, "because": "Beendet Schleife"}, {"text": "Continue", "correct": true, "because": "Überspringt Iteration"}, {"text": "Push", "correct": false, "because": "Git-spezifisch"}, {"text": "Design", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Break stoppt die Schleife. b) Continue beendet das Programm.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Continue überspringt nur"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Schleifensteuerung?', 4, '[{"text": "Bedingung", "correct": false, "because": "Steuert Ablauf"}, {"text": "Steuerbefehle", "correct": false, "because": "Break und Continue nötig"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob break in jeder Schleife nutzbar ist?', 2, '[{"text": "Ja", "correct": true, "because": "In For und While einsetzbar"}, {"text": "Nein", "correct": false, "because": "Universell nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um eine Schleife sofort zu stoppen?', 3, '[{"text": "break", "correct": true, "because": "Beendet Schleife"}, {"text": "continue", "correct": false, "because": "Überspringt nur"}, {"text": "return", "correct": false, "because": "Funktion beenden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten break und continue?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Steuerung anpassbar"}, {"text": "Effizienz", "correct": true, "because": "Vermeidet unnötige Durchläufe"}, {"text": "Datenkompression", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Break ist für Abbruch. b) Continue stoppt die Schleife. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Continue überspringt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Schleifensteuerung?', 4, '[{"text": "Schleifenbedingung", "correct": false, "because": "Grundlage der Schleife"}, {"text": "Steuerbefehle", "correct": false, "because": "Break und Continue"}, {"text": "Grafiksoftware", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Überspringt continue die gesamte Schleife?', 2, '[{"text": "Nein", "correct": true, "because": "Nur aktuelle Iteration"}, {"text": "Ja", "correct": false, "because": "Break beendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Möglichkeiten habe ich zur Steuerung?', 4, '[{"text": "Abbruch mit break", "correct": true, "because": "Stoppt Schleife"}, {"text": "Überspringen mit continue", "correct": true, "because": "Nächste Iteration"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass break die Performance senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann sie sogar steigern"}, {"text": "Ja", "correct": false, "because": "Kein direkter Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von break?', 3, '[{"text": "Klare Abbruchbedingung", "correct": true, "because": "Sichert Kontrolle"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Korrektheit zählt"}, {"text": "UI-Design", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Continue hilft bei Effizienz. b) Break ist optional.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) spart Durchläufe, b) nicht zwingend"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es ohne Steuerung?', 5, '[{"text": "Unnötige Iterationen", "correct": true, "because": "Ohne continue"}, {"text": "Endlosschleifen", "correct": true, "because": "Ohne break möglich"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Steuerung unwichtig?', 3, '[{"text": "Break-Position", "correct": false, "because": "Steuert Abbruch"}, {"text": "Continue-Logik", "correct": false, "because": "Definiert Überspringen"}, {"text": "Serverleistung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann break mehrere Schleifen beenden?', 3, '[{"text": "Nein", "correct": true, "because": "Nur aktuelle Schleife"}, {"text": "Ja", "correct": false, "because": "Sprachabhängig, meist nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob continue die Schleife anhält?', 2, '[{"text": "Nein", "correct": true, "because": "Nur überspringen"}, {"text": "Ja", "correct": false, "because": "Läuft weiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um bei einer Bedingung abzubrechen?', 4, '[{"text": "break", "correct": true, "because": "Stoppt Schleife sofort"}, {"text": "continue", "correct": false, "because": "Überspringt nur"}, {"text": "exit", "correct": false, "because": "Programmende"}]');
